#include <algorithm>
#include <cstdint>
#include <iostream>
#include <numeric>
#include <stdexcept>
#include <vector>
using namespace std;
using I=long long; using Rows=vector<int>;
void need(bool c,const char*m){if(!c)throw runtime_error(m);}
vector<I> starts(const Rows&a){int n=a.size(),M=1<<n;vector<I>dp(M*n),s(n);for(int i=0;i<n;i++)dp[(1<<i)*n+i]=1;for(int S=1;S<M;S++)for(int i=0;i<n;i++)if(S>>i&1){I z=dp[S*n+i];for(int j=0;j<n;j++)if(!(S>>j&1)&&(a[j]>>i&1))dp[(S|1<<j)*n+j]+=z;}for(int i=0;i<n;i++)s[i]=dp[(M-1)*n+i];return s;}
bool strong(const Rows&a){int n=a.size();for(int i=0;i<n;i++){int S=1<<i,old=-1;while(S!=old){old=S;for(int j=0;j<n;j++)if(S>>j&1)S|=a[j];}if(S!=(1<<n)-1)return false;}return true;}
Rows sub(const Rows&a,const vector<int>&v){Rows b(v.size());for(int i=0;i<(int)v.size();i++)for(int j=0;j<(int)v.size();j++)if(a[v[i]]>>v[j]&1)b[i]|=1<<j;return b;}
Rows add(const Rows&a,int A){Rows b=a;int n=a.size();for(int i=0;i<n;i++)if(!(A>>i&1))b[i]|=1<<n;b.push_back(A);return b;}
Rows pairadd(const Rows&a){Rows b=a;int n=a.size();for(int&i:b)i|=1<<n;b.push_back(1<<(n+1));b.push_back((1<<n)-1);return b;}
I growthchecks=0,pairchecks=0,mixedchecks=0,subsetchecks=0;
void growth(const Rows&a){int n=a.size();if(n==1)return;vector<int>v;for(int x=0;x<n&&v.empty();x++)for(int y=x+1;y<n&&v.empty();y++)for(int z=y+1;z<n&&v.empty();z++)if(strong(sub(a,{x,y,z})))v={x,y,z};need(v.size()==3,"triangle missing");while((int)v.size()<n){Rows old=sub(a,v);auto os=starts(old);int U=0;for(int x:v)U|=1<<x;int xpick=-1;for(int x=0;x<n;x++)if(!(U>>x&1)){int A=a[x]&U;if(A&&A!=U){xpick=x;break;}}if(xpick>=0){v.push_back(xpick);Rows now=sub(a,v);need(strong(now),"mixed growth weak");auto ns=starts(now);for(int i=0;i<(int)os.size();i++)need(ns[i]>=os[i],"mixed nonmonotone");growthchecks++;}else{int aa=-1,dd=-1;for(int d=0;d<n;d++)if(!(U>>d&1)&&!(a[d]&U))for(int z=0;z<n;z++)if(!(U>>z&1)&&(a[z]&U)==U&&(a[d]>>z&1)){dd=d;aa=z;}need(aa>=0,"uniform pair missing");int m=v.size();v.push_back(dd);v.push_back(aa);Rows now=sub(a,v);need(strong(now),"pair growth weak");auto ns=starts(now);I h=accumulate(os.begin(),os.end(),0LL);need(ns[m]==h&&ns[m+1]==h,"pair starts");for(int i=0;i<m;i++)need(ns[i]>=os[i],"pair nonmonotone");pairchecks++;}}}
int main(){I graphs=0,stronggraphs=0;vector<I>byorder(7),strongbyorder(7);for(int n=1;n<=6;n++){int N=1<<(n*(n-1)/2);for(int mask=0;mask<N;mask++){Rows a(n);int bit=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,bit++){if(mask>>bit&1)a[i]|=1<<j;else a[j]|=1<<i;}graphs++;byorder[n]++;if(!strong(a))continue;stronggraphs++;strongbyorder[n]++;auto s=starts(a),sorted=s;sort(sorted.begin(),sorted.end());I sum=0;for(int m=1;m<=n;m++){sum+=sorted[m-1];need(sum>=m*m/4+1,"endpoint bound");subsetchecks+=(1LL<<n)-1;}growth(a);if(n>=3&&n<=5){for(int A=1;A<(1<<n)-1;A++){Rows b=add(a,A);need(strong(b),"mixed child");auto ns=starts(b);I p=0;for(int i=0;i<n;i++)if(A>>i&1)p+=s[i];need(ns[n]==p,"newroot sum");vector<I>d(n);for(int i=0;i<n;i++){d[i]=ns[i]-s[i];need(d[i]>=0,"monotonicity");}sort(d.begin(),d.end());I inc=p;for(int m=0;m<=n;m++){if(m)inc+=d[m-1];need(inc>=(m+1)/2,"marked increment");mixedchecks++;}}Rows b=pairadd(a);auto ns=starts(b);I h=accumulate(s.begin(),s.end(),0LL);need(ns[n]==h&&ns[n+1]==h,"standalone pair");}}}cout<<"{\n  \"status\": \"PASS\",\n  \"labeled_graphs\": "<<graphs<<",\n  \"strong_graphs\": "<<stronggraphs<<",\n  \"strong_by_order\": [";for(int n=1;n<=6;n++){if(n>1)cout<<", ";cout<<strongbyorder[n];}cout<<"],\n  \"mixed_marked_size_checks\": "<<mixedchecks<<",\n  \"growth_mixed_steps\": "<<growthchecks<<",\n  \"growth_pair_steps\": "<<pairchecks<<",\n  \"scope\": \"All labeled tournaments through order6; all mixed extensions of strong inputs through order5. All-order proof is separate.\"\n}\n";}
